function generateMassDesignSkills(target: number): Skill[] {
  const skills: Skill[] = [];

  for (let i = 0; i < target; i += 1) {
    const n = i + 1;
    const screenIdx = i % MASS_DESIGN_SCREENS.length;
    const styleIdx = Math.floor(i / MASS_DESIGN_SCREENS.length) % MASS_DESIGN_STYLES.length;
    const layoutIdx = Math.floor(i / (MASS_DESIGN_SCREENS.length * MASS_DESIGN_STYLES.length)) % MASS_DESIGN_LAYOUTS.length;
    const themeIdx = Math.floor(i / (MASS_DESIGN_SCREENS.length * MASS_DESIGN_STYLES.length * MASS_DESIGN_LAYOUTS.length)) % MASS_DESIGN_THEMES.length;
    const screen = MASS_DESIGN_SCREENS[screenIdx];
    const style = MASS_DESIGN_STYLES[styleIdx];
    const layout = MASS_DESIGN_LAYOUTS[layoutIdx];
    const theme = MASS_DESIGN_THEMES[themeIdx];
    const screenEn = MASS_DESIGN_SCREENS_EN[screenIdx];
    const styleEn = MASS_DESIGN_STYLES_EN[styleIdx];
    const layoutEn = MASS_DESIGN_LAYOUTS_EN[layoutIdx];
    const themeEn = MASS_DESIGN_THEMES_EN[themeIdx];
    const cliType = MASS_DESIGN_CLI_TYPES[i % MASS_DESIGN_CLI_TYPES.length];
    const category = MASS_DESIGN_CATEGORIES[Math.floor(i / MASS_DESIGN_CLI_TYPES.length) % MASS_DESIGN_CATEGORIES.length];
    const emoji = MASS_DESIGN_EMOJIS[i % MASS_DESIGN_EMOJIS.length];
    const id = `g-design-mass-${String(n).padStart(4, '0')}`;

    skills.push({
      id,
      name: `${themeEn} ${screenEn} sample screen ${n}`,
      description: `${styleEn} style · ${layoutEn} layout`,
      emoji,
      command: `${theme} 제품의 ${screen} 샘플 화면을 ${style} 스타일과 ${layout} 레이아웃으로 설계해줘. 주요 상태(기본/로딩/빈화면/에러), 접근성, 반응형 기준을 포함해줘.`,
      cliType,
      category,
      tags: ['design', 'sample-screen', 'mass', 'generated', 'ui', 'ux', 'octo', screen, style, theme],
    });
  }

  return skills;
}

const MASS_DESIGN_SKILLS = generateMassDesignSkills(MASS_DESIGN_TARGET);

